echo "Publishing Forge Hub to wan-relay from this phone session..."
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

base64 -d >"$TMP/hub.tgz" <<'__FORGE_HUB_TGZ_B64__'
